using System;
using System.Collections.Generic;
using UnityEngine;

namespace Astrea;

public class AustraOmensHandler : ReferenceSingleton<AustraOmensHandler>
{
	[NonSerialized]
	[Header("Cellarius Omens")]
	public bool ApianLampOmenDataActive;

	[NonSerialized]
	public List<Action<GameObject>> OnDodgeOmenActions = new List<Action<GameObject>>();

	[NonSerialized]
	public Action MeteorShieldOmenAction;

	[NonSerialized]
	public Action ActivateSafeCriticalOmenAction;

	[NonSerialized]
	public Action DeactivateSafeCriticalOmenAction;

	[NonSerialized]
	public bool HiveModuleOmenActive;

	[NonSerialized]
	public Func<int> HiveModuleOmenCriticalMultiplierAction;

	[NonSerialized]
	public Func<int> HiveModuleOmenChanceAction;

	[NonSerialized]
	public Func<VacuumWingsOmenData.VacuumWingsValues> VacuumWingsOmenActive;

	[NonSerialized]
	public Action<int> TempestPollenOmenAction;

	public void ActivateOnDodgeOmen(GameObject unitThatDodged)
	{
		for (int i = 0; i < OnDodgeOmenActions.Count; i++)
		{
			OnDodgeOmenActions[i](unitThatDodged);
		}
	}

	public bool PlayerHaveActivateMeteorShieldOmenAndActivateIt()
	{
		if (MeteorShieldOmenAction != null)
		{
			MeteorShieldOmenAction();
			return true;
		}
		return false;
	}

	public void ActivateSafeCriticalOmen()
	{
		ActivateSafeCriticalOmenAction?.Invoke();
	}

	public void DeactivateSafeCriticalOmen()
	{
		DeactivateSafeCriticalOmenAction?.Invoke();
	}

	public int IsHiveModuleOmenActivateGetCriticalChanceModifierAmount()
	{
		if (HiveModuleOmenChanceAction != null)
		{
			return HiveModuleOmenChanceAction();
		}
		return 0;
	}

	public int IsHiveModuleOmenActivateGetCriticalMultiplierModifierAmountAndPlayFeedback()
	{
		if (HiveModuleOmenCriticalMultiplierAction != null)
		{
			return HiveModuleOmenCriticalMultiplierAction();
		}
		return 0;
	}

	public VacuumWingsOmenData.VacuumWingsValues IsVacuumWingsOmenActiveGetVacuumWingsValues()
	{
		if (VacuumWingsOmenActive != null)
		{
			return VacuumWingsOmenActive();
		}
		return null;
	}
}
